-- Signal to Story release: 0.5.0 step 5 (final: DB4 + DB5 + DB3 + retire V1)
-- Generated by testing/db/release.ts from supabase/migrations — do not edit by hand.
-- Brings the database from migration 20261125100000 to 20261126100300 (4 migrations) in ONE transaction.
-- Run it once, in the Supabase SQL editor or psql, AFTER taking a backup. Any error rolls everything back.

begin;

-- ── 1. Preflight: refuse to run on a database that is not in the expected state ──
do $preflight$
declare n bigint; t text;
begin
  if to_regclass('supabase_migrations.schema_migrations') is null then
    raise exception 'preflight: supabase_migrations.schema_migrations is missing';
  end if;
  select max(version) into t from supabase_migrations.schema_migrations;
  if t is distinct from '20261125100000' then
    raise exception 'preflight: expected last applied migration 20261125100000, found %', t;
  end if;
  if to_regclass('public.chat_sessions') is not null then
    raise exception 'preflight: the objects of this batch already exist — this release was applied before';
  end if;
  -- Every worker (agent and video) must be stopped: node RPCs, video tables and content_documents change shape.
  select count(*) into n from public.agent_jobs where status = 'running' and locked_until > now();
  if n > 0 then raise exception 'preflight: % agent job(s) hold a live lease; stop every worker and wait for the leases to expire', n; end if;
  -- Linked project assets are not carried over (database.md R3); refuse instead of silently dropping them.
  select count(*) into n from public.content_project_assets;
  if n > 0 then raise exception 'preflight: content_project_assets has % rows; they are not migrated — export them first', n; end if;
  -- External publishing tables are dropped without migration (DB-D3: empty live).
  select (select count(*) from public.publishing_channels) + (select count(*) from public.content_publications) + (select count(*) from public.publication_metrics) into n;
  if n > 0 then raise exception 'preflight: external publishing tables hold % rows; expected empty', n; end if;
  -- Retired video and knowledge tables must be empty (nothing to migrate).
  select (select count(*) from public.video_plans) + (select count(*) from public.video_storyboard_proposals) + (select count(*) from public.video_cost_entries)
       + (select count(*) from public.knowledge_entries) + (select count(*) from public.decision_memories) into n;
  if n > 0 then raise exception 'preflight: video / knowledge tables hold % rows; expected empty', n; end if;
  -- Reader-site tables: only the single site_settings row may exist (no published entries are lost).
  select (select count(*) from public.site_entries) + (select count(*) from public.site_entry_releases) + (select count(*) from public.site_resources) + (select count(*) from public.site_bookmarks) into n;
  if n > 0 then raise exception 'preflight: reader-site tables hold % rows; republish through publish_document after the release instead', n; end if;
end $preflight$;

-- ── 2. Pending migrations, in order ──

-- >>> 20261126100000_publish_on_documents.sql
-- DB4 (0.5): publishing lives on content_documents (docs/database.md §4.3, R7).
--   * publish_document copies the approved revision into the published_* columns. Later edits bump `revision`
--     but never touch published_*, so the reader site keeps showing what was approved.
--   * Mandate: a human-approved publish_site request bound to (document, revision) is required (MD001 / MD002).
--   * published_* columns can only be written by publish_document / unpublish_document / set_document_published_url.
--   * anon reads only the published columns of published rows (column grants + RLS). sense-site reads nothing else.
-- Retires: the local site_* tables (12) and their functions, and the external publishing tables
-- (publishing_channels, content_publications, publication_metrics) — all empty live; manual publishing just
-- records the external link in published_url.

-- ── 1. Drop the reader-site and external-publishing objects ──
drop trigger if exists document_invalidate_publications on public.content_documents;
drop function if exists private.invalidate_stale_publications();
drop function if exists public.publish_site_entry(uuid, uuid, integer, jsonb);
drop function if exists public.unpublish_site_entry(uuid, text);
drop table if exists
  public.site_bookmarks, public.site_topic_items, public.site_topics, public.site_resource_files, public.site_resources,
  public.site_release_events, public.site_entry_bodies, public.site_entry_releases, public.site_entries,
  public.site_categories, public.site_readers, public.site_settings
  cascade;
drop function if exists private.guard_site_row();
drop function if exists private.forbid_site_snapshot_mutation();
drop function if exists private.is_verified_reader();
drop function if exists private.site_validate_url(text, boolean);
drop table if exists public.publication_metrics, public.content_publications, public.publishing_channels cascade;

-- Approval targets: content_publication is gone; only documents (and video plans, 20261120100100) carry revisions.
create or replace function private.current_target_revision(p_target_type text, p_target_id text) returns integer
language plpgsql stable security definer set search_path='' as $$
declare r integer;
begin
 if p_target_type = 'content_document' then
  select d.revision into r from public.content_documents d where d.id::text = p_target_id;
  return r;
 elsif p_target_type = 'video_plan' then
  select v.revision into r from public.video_plans v where v.id::text = p_target_id;
  return r;
 end if;
 return null;
end; $$;

create or replace function private.expire_stale_document_approvals() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.revision <> old.revision then
  update public.approval_requests set status = 'expired'
  where organization_id = new.organization_id and kind = 'approval' and status in ('pending','approved')
   and target_type = 'content_document' and target_id = new.id::text
   and coalesce(target_revision, 0) < new.revision;
 end if;
 return new;
end; $$;

-- ── 2. Published columns ──
alter table public.content_documents
  add column published_revision integer check (published_revision is null or published_revision >= 1),
  add column published_title text check (published_title is null or char_length(published_title) <= 200),
  add column published_body text check (published_body is null or char_length(published_body) <= 100000),
  add column published_meta jsonb not null default '{}'::jsonb
    check (jsonb_typeof(published_meta) = 'object' and pg_column_size(published_meta) <= 65536),
  add column published_at timestamptz,
  add column published_url text not null default ''
    check (published_url = '' or (published_url ~ '^https?://[^[:space:]<>"]+$' and char_length(published_url) <= 2000)),
  add column slug text check (slug is null or (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length(slug) <= 96)),
  add constraint content_documents_published_shape check (
    published_at is null or (published_revision is not null and published_title is not null and published_body is not null and slug is not null));
create unique index content_documents_org_slug_key on public.content_documents (organization_id, slug) where slug is not null;
create index content_documents_published_idx on public.content_documents (published_at desc) where published_at is not null;
comment on column public.content_documents.published_at is '读者站上线时间；为空表示未发布或已下线。published_* 只能由发布 RPC 写入。';
comment on column public.content_documents.published_url is '人工发布到外部平台后回填的链接（不做数据复盘）。';

-- Only the publishing RPCs (which set app.publishing for their own statement) may write published_*.
create function private.guard_document_publish_columns() returns trigger language plpgsql set search_path='' as $$
begin
 if coalesce(current_setting('app.publishing', true), '') = 'on' then return new; end if;
 if tg_op = 'INSERT' then
  if new.published_revision is not null or new.published_title is not null or new.published_body is not null
     or new.published_meta <> '{}'::jsonb or new.published_at is not null or new.published_url <> '' or new.slug is not null then
   raise exception '发布信息只能通过发布操作写入' using errcode = '42501';
  end if;
 elsif new.published_revision is distinct from old.published_revision or new.published_title is distinct from old.published_title
    or new.published_body is distinct from old.published_body or new.published_meta is distinct from old.published_meta
    or new.published_at is distinct from old.published_at or new.published_url is distinct from old.published_url
    or new.slug is distinct from old.slug then
  raise exception '发布信息只能通过发布操作写入' using errcode = '42501';
 end if;
 return new;
end; $$;
revoke all on function private.guard_document_publish_columns() from public, anon, authenticated;
create trigger document_publish_columns_guard before insert or update on public.content_documents
  for each row execute function private.guard_document_publish_columns();

-- Reader site: anon sees only the published columns of published rows.
revoke all on public.content_documents from anon;
grant select (id, organization_id, platform, slug, published_revision, published_title, published_body, published_meta, published_at, published_url)
  on public.content_documents to anon;
create policy content_documents_public_read on public.content_documents for select to anon using (published_at is not null);

-- ── 3. Publishing RPCs ──
create function private.https_url_ok(value text, allow_empty boolean default true) returns boolean
language sql immutable set search_path='' as $$
  select case when value is null or value = '' then allow_empty
    else value ~ '^https://[^[:space:]<>"]+$' and char_length(value) <= 2000 end;
$$;
revoke all on function private.https_url_ok(text, boolean) from public, anon, authenticated;

create function public.publish_document(p_document_id uuid, p_revision integer, p_meta jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_uid uuid := (select auth.uid());
  d public.content_documents;
  v_item jsonb;
  v_slug text := lower(btrim(coalesce(p_meta ->> 'slug', '')));
  v_summary text := btrim(coalesce(p_meta ->> 'summary', ''));
  v_format text := coalesce(nullif(p_meta ->> 'format', ''), 'article');
  v_cover text := btrim(coalesce(p_meta ->> 'cover_url', ''));
  v_cover_alt text := btrim(coalesce(p_meta ->> 'cover_alt', ''));
  v_media jsonb := coalesce(p_meta -> 'media', '[]'::jsonb);
  v_refs jsonb := coalesce(p_meta -> 'source_refs', '[]'::jsonb);
  v_meta jsonb;
  v_action text;
begin
  if v_uid is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
    raise exception '需要登录后台账号' using errcode = '42501';
  end if;
  if p_meta is null or jsonb_typeof(p_meta) <> 'object' then
    raise exception '发布参数格式无效' using errcode = '22023';
  end if;
  select * into d from public.content_documents where id = p_document_id for update;
  if not found then raise exception '稿件不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(d.organization_id, 'content.publish') then
    raise exception '需要该组织的发布权限' using errcode = '42501';
  end if;
  if d.status <> 'approved' or d.revision <> p_revision then
    raise exception '仅可发布当前已人工审核通过的版本' using errcode = 'P0001';
  end if;
  if btrim(d.body) = '' then raise exception '已审核版本没有可发布的正文' using errcode = 'P0001'; end if;

  if v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(v_slug) > 96 then
    raise exception '链接标识仅允许小写字母、数字和连字符（最多 96 字）' using errcode = '22023';
  end if;
  if char_length(v_summary) not between 1 and 500 then
    raise exception '请填写 1–500 字的人工摘要' using errcode = '22023';
  end if;
  if v_format not in ('article', 'tutorial', 'video', 'comic', 'resource') then
    raise exception '无效的内容形式' using errcode = '22023';
  end if;
  if not private.https_url_ok(v_cover) or char_length(v_cover_alt) > 200 or (v_cover <> '' and v_cover_alt = '') then
    raise exception '封面需为 https 地址并填写替代文本' using errcode = '22023';
  end if;
  if jsonb_typeof(v_media) <> 'array' or jsonb_array_length(v_media) > 20 then
    raise exception '媒体引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_media) loop
    if jsonb_typeof(v_item) <> 'object' or coalesce(v_item ->> 'kind', '') not in ('image', 'video')
      or not private.https_url_ok(v_item ->> 'url', false) or not private.https_url_ok(coalesce(v_item ->> 'poster', ''))
      or char_length(coalesce(v_item ->> 'alt', '')) > 200
      or (v_item ->> 'kind' = 'image' and btrim(coalesce(v_item ->> 'alt', '')) = '') then
      raise exception '媒体需为 https 地址，图片需填写替代文本' using errcode = '22023';
    end if;
  end loop;
  if v_format = 'video' and not exists (select 1 from jsonb_array_elements(v_media) m where m.value ->> 'kind' = 'video') then
    raise exception '视频内容需要提供视频地址' using errcode = '22023';
  end if;
  if jsonb_typeof(v_refs) <> 'array' or jsonb_array_length(v_refs) > 50 then
    raise exception '来源引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_refs) loop
    if jsonb_typeof(v_item) <> 'object' or char_length(btrim(coalesce(v_item ->> 'title', ''))) not between 1 and 200
      or not private.https_url_ok(v_item ->> 'url', false) then
      raise exception '来源引用需包含标题和 https 地址' using errcode = '22023';
    end if;
  end loop;
  if exists (select 1 from public.content_documents o where o.organization_id = d.organization_id and o.slug = v_slug and o.id <> d.id) then
    raise exception '链接标识已被其他稿件使用' using errcode = '23505';
  end if;
  v_meta := jsonb_build_object('summary', v_summary, 'format', v_format, 'cover_url', v_cover, 'cover_alt', v_cover_alt,
    'media', v_media, 'source_refs', v_refs);

  -- Idempotent retry: already live with the same revision and metadata needs no fresh approval.
  if d.published_at is not null and d.published_revision = p_revision and d.slug = v_slug and d.published_meta = v_meta then
    return jsonb_build_object('document_id', d.id, 'revision', p_revision, 'slug', v_slug, 'action', 'unchanged', 'unchanged', true);
  end if;

  -- Database-level Mandate: a human-approved publish_site request bound to this document and revision.
  if not exists (
    select 1 from public.approval_requests a
    where a.organization_id = d.organization_id and a.kind = 'approval' and a.action = 'publish_site'
      and a.target_type = 'content_document' and a.target_id = d.id::text and a.target_revision = p_revision
      and a.status = 'approved' and a.expires_at > now()
  ) then
    if exists (
      select 1 from public.approval_requests a
      where a.organization_id = d.organization_id and a.kind = 'approval' and a.action = 'publish_site'
        and a.target_type = 'content_document' and a.target_id = d.id::text and a.target_revision = p_revision
        and (a.status = 'expired' or (a.status = 'approved' and a.expires_at <= now()))
    ) then
      raise exception '发布批准已过期，请重新请求批准' using errcode = 'MD002';
    end if;
    raise exception '缺少该版本的有效发布批准，请先请求并获得批准' using errcode = 'MD001';
  end if;

  v_action := case when d.published_at is not null then 'replace' when d.published_revision is not null then 'republish' else 'publish' end;
  perform set_config('app.publishing', 'on', true);
  update public.content_documents set
    published_revision = p_revision, published_title = d.title, published_body = d.body, published_meta = v_meta,
    published_at = now(), slug = v_slug
  where id = d.id;
  perform set_config('app.publishing', 'off', true);

  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (d.organization_id, v_uid, 'content.published', 'content_document', d.id::text,
    jsonb_build_object('revision', p_revision, 'slug', v_slug, 'action', v_action));
  return jsonb_build_object('document_id', d.id, 'revision', p_revision, 'slug', v_slug, 'action', v_action, 'unchanged', false);
end; $$;
revoke all on function public.publish_document(uuid, integer, jsonb) from public, anon, service_role;
grant execute on function public.publish_document(uuid, integer, jsonb) to authenticated;

-- Take a document off the reader site. The published snapshot and audit history stay; anon can no longer read it.
create function public.unpublish_document(p_document_id uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_uid uuid := (select auth.uid()); d public.content_documents;
begin
  if v_uid is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
    raise exception '需要登录后台账号' using errcode = '42501';
  end if;
  if char_length(coalesce(p_note, '')) > 1000 then raise exception '下线说明不超过 1000 字' using errcode = '22023'; end if;
  select * into d from public.content_documents where id = p_document_id for update;
  if not found then raise exception '稿件不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(d.organization_id, 'content.publish') then
    raise exception '需要该组织的发布权限' using errcode = '42501';
  end if;
  if d.published_at is null then
    return jsonb_build_object('document_id', d.id, 'unchanged', true);
  end if;
  perform set_config('app.publishing', 'on', true);
  update public.content_documents set published_at = null where id = d.id;
  perform set_config('app.publishing', 'off', true);
  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (d.organization_id, v_uid, 'content.unpublished', 'content_document', d.id::text,
    jsonb_build_object('revision', d.published_revision, 'note', coalesce(p_note, '')));
  return jsonb_build_object('document_id', d.id, 'unchanged', false);
end; $$;
revoke all on function public.unpublish_document(uuid, text) from public, anon, service_role;
grant execute on function public.unpublish_document(uuid, text) to authenticated;

-- Manual publishing elsewhere: record the external link (empty string clears it).
create function public.set_document_published_url(p_document_id uuid, p_url text)
returns void language plpgsql security definer set search_path='' as $$
declare v_uid uuid := (select auth.uid()); d public.content_documents; v_url text := btrim(coalesce(p_url, ''));
begin
  if v_uid is null then raise exception '需要登录后台账号' using errcode = '42501'; end if;
  select * into d from public.content_documents where id = p_document_id for update;
  if not found then raise exception '稿件不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(d.organization_id, 'content.publish') then
    raise exception '需要该组织的发布权限' using errcode = '42501';
  end if;
  if v_url <> '' and (v_url !~ '^https?://[^[:space:]<>"]+$' or char_length(v_url) > 2000) then
    raise exception '请填写 http(s) 链接' using errcode = '22023';
  end if;
  if v_url <> '' and d.status <> 'approved' then
    raise exception '仅可为已审核通过的稿件登记发布链接' using errcode = 'P0001';
  end if;
  perform set_config('app.publishing', 'on', true);
  update public.content_documents set published_url = v_url where id = d.id;
  perform set_config('app.publishing', 'off', true);
  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (d.organization_id, v_uid, 'content.published_url', 'content_document', d.id::text,
    jsonb_build_object('revision', d.revision, 'url', v_url));
end; $$;
revoke all on function public.set_document_published_url(uuid, text) from public, anon, service_role;
grant execute on function public.set_document_published_url(uuid, text) to authenticated;
-- <<< 20261126100000_publish_on_documents.sql

-- >>> 20261126100100_video_mvp.sql
-- DB5 (0.5): video studio trimmed to the MVP (docs/database.md §4.6, R5, R6).
--   * video_plans hang off a work item (project_id → work_item_id); source_proposal_id is gone.
--   * The AI writes a draft plan + shots directly (node_write_video_draft); humans edit them in place.
--     Paid rendering still needs an approval bound to the plan revision (unchanged).
--   * No cost ledger: video_cost_entries, video_plan_cost_summary and the per-shot cost columns are dropped.
--     Estimates are computed on the fly (private.video_job_estimate); the paid-render approval keeps its
--     estimate in payload.estimated_cost_cents (approval_requests.estimated_cost_cents is dropped).
--   * video_storyboard_proposals and the accept/reject RPCs are retired. Knowledge for storyboards comes from
--     the repo's knowledge-base/ files read by the worker (node_storyboard_knowledge is dropped).
-- All video tables are empty live.

-- ── 1. Retire proposals, ledger and summary ──
drop function if exists public.accept_video_storyboard_proposal(uuid, text);
drop function if exists public.reject_video_storyboard_proposal(uuid, text);
drop function if exists public.node_save_storyboard_proposal(text, uuid, bigint, jsonb);
drop function if exists public.node_storyboard_knowledge(text, uuid);
drop view if exists public.video_plan_cost_summary;
drop trigger if exists video_cost_entry_apply on public.video_cost_entries;
drop function if exists private.apply_video_cost_entry();
drop table if exists public.video_cost_entries;
alter table public.video_plans drop constraint if exists video_plans_source_proposal_fkey;
drop table if exists public.video_storyboard_proposals;
drop function if exists private.guard_video_proposal();
drop trigger if exists video_plan_reprice on public.video_plans;
drop function if exists private.reprice_video_shots();

-- ── 2. video_plans: work item instead of project; source document without the revision history table ──
drop index if exists public.video_plans_project_idx;
drop index if exists public.video_plans_proposal_idx;
alter table public.video_plans drop constraint if exists video_plans_organization_id_project_id_fkey;
alter table public.video_plans drop constraint if exists video_plans_organization_id_source_document_id_source_docum_fkey;
do $$
declare c text;
begin
  -- the composite FK to content_revisions has a generated name; drop it by definition
  for c in select conname from pg_constraint where conrelid = 'public.video_plans'::regclass and contype = 'f'
           and pg_get_constraintdef(oid) like '%content_revisions%' loop
    execute format('alter table public.video_plans drop constraint %I', c);
  end loop;
end $$;
alter table public.video_plans drop column project_id, drop column source_proposal_id;
alter table public.video_plans add column work_item_id uuid,
  add constraint video_plans_work_item_fkey foreign key (organization_id, work_item_id) references public.work_items(organization_id, id) on delete set null (work_item_id),
  add constraint video_plans_source_document_fkey foreign key (organization_id, source_document_id) references public.content_documents(organization_id, id) on delete set null (source_document_id);
create index video_plans_work_item_idx on public.video_plans (organization_id, work_item_id);

-- ── 3. video_shots: no cost columns ──
alter table public.video_shots drop column estimated_cost_cents, drop column actual_cost_cents;

create or replace function private.guard_video_plan() returns trigger language plpgsql security definer set search_path='' as $$
declare content_changed boolean;
begin
 if tg_op = 'INSERT' then
  new.revision := 1; new.status := 'draft'; new.composed_video_asset_id := null; new.final_duration_ms := null; new.error := null;
  new.created_at := now(); new.updated_at := now(); new.updated_by := coalesce(auth.uid(), new.created_by);
  if new.work_item_id is not null and not exists (select 1 from public.work_items w where w.id = new.work_item_id and w.organization_id = new.organization_id) then
   raise exception '事项不存在或不属于该组织' using errcode='check_violation';
  end if;
  return new;
 end if;
 if new.organization_id is distinct from old.organization_id or new.created_by is distinct from old.created_by
  or new.created_at is distinct from old.created_at then
  raise exception '分镜计划的归属不可修改' using errcode='check_violation';
 end if;
 if not private.video_asset_in_org(new.composed_video_asset_id, new.organization_id) then
  raise exception '成片资产不属于该组织' using errcode='check_violation';
 end if;
 content_changed := (new.title, new.aspect_ratio, new.target_seconds, new.style, new.default_voice, new.tts_provider, new.bgm_track,
   new.work_item_id, new.source_document_id, new.source_document_revision)
  is distinct from (old.title, old.aspect_ratio, old.target_seconds, old.style, old.default_voice, old.tts_provider, old.bgm_track,
   old.work_item_id, old.source_document_id, old.source_document_revision);
 if content_changed then
  if old.status = 'rendering' or private.video_plan_locked(old.id) then
   raise exception '渲染进行中，分镜已锁定' using errcode='check_violation';
  end if;
  new.revision := old.revision + 1;
  if new.status in ('rendered','failed') then new.status := 'draft'; end if;
 end if;
 if new.revision < old.revision then raise exception 'revision 只能递增' using errcode='check_violation'; end if;
 new.updated_at := now();
 if auth.uid() is not null then new.updated_by := auth.uid(); end if;
 return new;
end; $$;

create or replace function private.guard_video_shot() returns trigger language plpgsql security definer set search_path='' as $$
declare p public.video_plans; visual_changed boolean := false; audio_changed boolean := false;
begin
 if tg_op = 'DELETE' then
  if private.video_plan_locked(old.plan_id) then raise exception '渲染进行中，分镜已锁定' using errcode='check_violation'; end if;
  return old;
 end if;
 select * into p from public.video_plans where id = new.plan_id;
 if tg_op = 'INSERT' then
  if p.organization_id is distinct from new.organization_id then raise exception '镜头与计划不属于同一组织' using errcode='check_violation'; end if;
  if private.video_plan_locked(new.plan_id) then raise exception '渲染进行中，分镜已锁定' using errcode='check_violation'; end if;
  new.render_status := 'pending'; new.audio_asset_id := null; new.video_asset_id := null; new.actual_duration_ms := null;
  new.error := null; new.created_at := now();
 else
  if new.organization_id is distinct from old.organization_id or new.plan_id is distinct from old.plan_id
   or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
   raise exception '镜头归属不可修改' using errcode='check_violation';
  end if;
  visual_changed := (new.position, new.shot_size, new.camera_motion, new.motion_mode, new.visual_prompt, new.sfx_description,
    new.target_duration_ms, new.keyframe_asset_id)
   is distinct from (old.position, old.shot_size, old.camera_motion, old.motion_mode, old.visual_prompt, old.sfx_description,
    old.target_duration_ms, old.keyframe_asset_id);
  audio_changed := (new.narration, new.voice) is distinct from (old.narration, old.voice);
  if visual_changed or audio_changed then
   if private.video_plan_locked(old.plan_id) then raise exception '渲染进行中，分镜已锁定' using errcode='check_violation'; end if;
   -- position-only changes (reorder) do not invalidate rendered media
   if audio_changed then new.audio_asset_id := null; new.actual_duration_ms := null; end if;
   if audio_changed or (new.shot_size, new.camera_motion, new.motion_mode, new.visual_prompt, new.target_duration_ms, new.keyframe_asset_id)
     is distinct from (old.shot_size, old.camera_motion, old.motion_mode, old.visual_prompt, old.target_duration_ms, old.keyframe_asset_id) then
    if old.render_status in ('queued','rendered','failed') then new.render_status := 'pending'; end if;
    new.video_asset_id := null; new.error := null;
   end if;
  elsif not private.video_shot_transition_allowed(old.render_status, new.render_status) then
   raise exception '非法镜头渲染状态迁移: % -> %', old.render_status, new.render_status using errcode='check_violation';
  end if;
 end if;
 if not (private.video_asset_in_org(new.keyframe_asset_id, new.organization_id) and private.video_asset_in_org(new.audio_asset_id, new.organization_id)
   and private.video_asset_in_org(new.video_asset_id, new.organization_id)) then
  raise exception '资产不属于该组织' using errcode='check_violation';
 end if;
 new.updated_at := now();
 return new;
end; $$;

revoke all on public.video_plans from authenticated;
grant select, delete on public.video_plans to authenticated;
grant insert (organization_id, work_item_id, source_document_id, source_document_revision, title, aspect_ratio, target_seconds, style, default_voice, tts_provider, bgm_track, created_by)
 on public.video_plans to authenticated;
grant update (work_item_id, source_document_id, source_document_revision, title, aspect_ratio, target_seconds, style, default_voice, tts_provider, bgm_track)
 on public.video_plans to authenticated;

-- ── 4. Approval estimate lives in payload ──
update public.approval_requests set payload = payload || jsonb_build_object('estimated_cost_cents', estimated_cost_cents)
 where estimated_cost_cents is not null;

create or replace function private.enforce_job_mandate() returns trigger language plpgsql security definer set search_path='' as $$
declare
 mandate_action text := private.job_type_mandate_action(new.kind);
 v_target_type text := new.payload->'target'->>'type';
 v_target_id text := new.payload->'target'->>'id';
 v_target_rev integer := case when (new.payload->'target'->>'revision') ~ '^[0-9]{1,9}$' then (new.payload->'target'->>'revision')::integer end;
 v_approval uuid := case when (new.payload->>'approval_request_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  then (new.payload->>'approval_request_id')::uuid end;
 v_plan public.video_plans; v_est jsonb; v_approved numeric; v_used numeric;
begin
 if private.is_video_render_job(new.kind) and new.status in ('queued','running','succeeded')
  and (tg_op = 'INSERT' or new.status is distinct from old.status) then
  select * into v_plan from public.video_plans where id::text = v_target_id and organization_id = new.organization_id;
  if v_target_type is distinct from 'video_plan' or not found then
   raise exception '视频任务必须指向本组织的分镜计划' using errcode='check_violation';
  end if;
  if tg_op = 'INSERT' then
   if auth.uid() is not null and not private.has_organization_permission(new.organization_id, 'content.manage') then
    raise exception '没有视频创作权限' using errcode='42501';
   end if;
   if v_target_rev is distinct from v_plan.revision then
    raise exception '分镜计划版本已变化，请刷新后重试' using errcode='check_violation';
   end if;
   if new.kind <> 'video_compose' and not exists (
    select 1 from public.video_shots s where s.plan_id = v_plan.id and s.id::text = new.payload->>'shot_id'
   ) then raise exception '镜头不存在或不属于该计划' using errcode='check_violation'; end if;
  elsif new.status = 'running' and v_target_rev is distinct from v_plan.revision then
   -- Content changed while queued: never render outdated content (paid or free).
   new.status := 'failed'; new.node_id := null; new.locked_until := null;
   new.error := '分镜已修改（版本变化），任务作废，请重新提交'; new.error_code := 'stale_target';
   return new;
  end if;
  v_est := private.video_job_estimate(new.kind, v_plan.id, new.payload);
  if tg_op = 'INSERT' then
   new.payload := new.payload || jsonb_build_object('server_estimate', v_est);
  end if;
  if not (v_est->>'requires_approval')::boolean then
   return new;  -- free / below threshold: no approval needed
  end if;
  mandate_action := 'paid_video_render';
  if tg_op = 'INSERT' and v_approval is not null then
   select case when (payload->>'estimated_cost_cents') ~ '^[0-9]+(\.[0-9]+)?$' then (payload->>'estimated_cost_cents')::numeric end
   into v_approved from public.approval_requests where id = v_approval;
   -- attempts = 0: never claimed
   select coalesce(sum(coalesce((j.payload->'server_estimate'->>'cost_cents')::numeric, 0)), 0) into v_used
   from public.agent_jobs j where j.payload->>'approval_request_id' = v_approval::text and not (j.status = 'cancelled' and j.attempts = 0);
   if v_approved is null or v_used + (v_est->>'cost_cents')::numeric > v_approved then
    raise exception '超出已批准金额（已用 %，本次 %，批准 %），请重新申请批准', v_used, v_est->>'cost_cents', coalesce(v_approved, 0) using errcode='42501';
   end if;
  end if;
 end if;

 if mandate_action is null or new.status not in ('queued','running','succeeded') then return new; end if;
 -- approval and target are immutable (guard), so a same-status update is a heartbeat on a validated job
 if tg_op = 'UPDATE' and new.status = old.status then return new; end if;
 if v_approval is null or v_target_type is null or v_target_id is null
  or not private.approval_is_valid(v_approval, new.organization_id, mandate_action, v_target_type, v_target_id) then
  if tg_op = 'INSERT' or new.status = 'succeeded' then
   raise exception '任务 [%] 需要针对同一对象与版本的有效人工批准 (Mandate)', new.kind using errcode='42501';
  end if;
  -- Approval expired / revision changed while queued: park the job for a human.
  new.status := 'blocked_needs_human'; new.node_id := null; new.locked_until := null;
  new.error := '人工批准已失效（版本变化或过期），请重新批准'; new.error_code := 'mandate_invalid';
 end if;
 return new;
end; $$;

-- The estimate argument stays for call compatibility and is stored in payload.estimated_cost_cents.
create or replace function public.create_approval_request(p_organization_id uuid, p_action text, p_target_type text, p_target_id text,
 p_target_revision integer default null, p_summary text default '', p_payload jsonb default '{}'::jsonb,
 p_estimated_cost_cents integer default null, p_requested_by_job uuid default null)
returns public.approval_requests language plpgsql security definer set search_path='' as $$
declare a public.approval_requests; current_rev integer; v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
 if auth.uid() is not null then
  if not private.has_organization_permission(p_organization_id,'content.manage') then
   raise exception '没有发起批准请求的权限' using errcode='42501';
  end if;
 elsif coalesce(auth.role(), '') <> 'service_role' then  -- PostgREST sets role from the service_role JWT
  raise exception '需要登录' using errcode='42501';
 elsif p_requested_by_job is null or not exists (
  select 1 from public.agent_jobs j where j.id = p_requested_by_job and j.organization_id = p_organization_id
 ) then
  raise exception 'Agent 发起的批准请求必须关联本组织任务' using errcode='check_violation';
 end if;
 if p_estimated_cost_cents is not null then
  if p_estimated_cost_cents < 0 then raise exception '预估费用不能为负' using errcode='check_violation'; end if;
  v_payload := v_payload || jsonb_build_object('estimated_cost_cents', p_estimated_cost_cents);
 end if;
 current_rev := private.current_target_revision(p_target_type, p_target_id);
 if p_target_type = 'content_document' and (current_rev is null or current_rev is distinct from p_target_revision) then
  raise exception '目标不存在或版本已变化' using errcode='check_violation';
 end if;
 select * into a from public.approval_requests
 where organization_id = p_organization_id and action = p_action and target_type = p_target_type and target_id = p_target_id
  and coalesce(target_revision,0) = coalesce(p_target_revision,0) and status = 'pending';
 if found then return a; end if;
 insert into public.approval_requests(organization_id, action, target_type, target_id, target_revision, summary, payload,
  requested_by_job, requested_by)
 values (p_organization_id, p_action, p_target_type, p_target_id, p_target_revision, coalesce(p_summary,''), v_payload,
  p_requested_by_job, auth.uid())
 returning * into a;
 return a;
end; $$;

alter table public.approval_requests drop column estimated_cost_cents;

-- ── 5. Storyboard job targets a work item ──
drop function if exists public.enqueue_video_storyboard_job(uuid, text, jsonb, uuid, text);
create function public.enqueue_video_storyboard_job(p_organization_id uuid, p_outline text, p_options jsonb default '{}'::jsonb,
 p_work_item_id uuid default null, p_idempotency_key text default null)
returns public.agent_jobs language plpgsql security definer set search_path='' as $$
declare v_key text; v_opts jsonb := coalesce(p_options, '{}'::jsonb);
begin
 if auth.uid() is null or not private.has_organization_permission(p_organization_id, 'content.manage') then
  raise exception '没有视频创作权限' using errcode='42501';
 end if;
 if char_length(btrim(coalesce(p_outline, ''))) not between 10 and 20000 then
  raise exception '大纲需要 10–20000 字' using errcode='check_violation';
 end if;
 if jsonb_typeof(v_opts) <> 'object' then raise exception '选项格式无效' using errcode='check_violation'; end if;
 v_key := coalesce(nullif(btrim(p_idempotency_key), ''), 'video_storyboard:' || encode(extensions.digest(btrim(p_outline) || v_opts::text || coalesce(p_work_item_id::text, ''), 'sha256'), 'hex'));
 return public.enqueue_agent_job(p_organization_id, 'video_storyboard', left(v_key, 200),
  jsonb_build_object('schema_version', 1, 'outline', btrim(p_outline),
   'aspect_ratio', coalesce(v_opts->>'aspect_ratio', '9:16'), 'target_seconds', coalesce((v_opts->>'target_seconds')::integer, 30),
   'style', coalesce(v_opts->>'style', ''), 'default_voice', coalesce(v_opts->>'default_voice', 'zh-CN-XiaoxiaoNeural')),
  null, null, null, coalesce((v_opts->>'budget_cents')::integer, 100), 3, null, p_work_item_id);
end; $$;
revoke all on function public.enqueue_video_storyboard_job(uuid, text, jsonb, uuid, text) from public, anon, service_role;
grant execute on function public.enqueue_video_storyboard_job(uuid, text, jsonb, uuid, text) to authenticated;

-- ── 6. The AI writes a draft plan directly (idempotent per job: result.plan_id) ──
-- Core (service_role, used by the SQL backend in tests/demos); node_write_video_draft wraps it with the node token check.
create function public.write_video_draft(p_job_id uuid, p_lease_epoch bigint, p_draft jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare j public.agent_jobs; v_plan uuid; v_shot jsonb; v_pos integer := 0;
begin
 select * into j from public.agent_jobs where id = p_job_id for update;
 if not found or j.status <> 'running' then raise exception '任务不存在或未在运行' using errcode='P0002'; end if;
 if j.lease_epoch is distinct from p_lease_epoch then raise exception '任务租约已失效（lease_epoch 不匹配），拒绝写入' using errcode='P0002'; end if;
 if j.kind <> 'video_storyboard' then raise exception '只有分镜任务可以写入分镜草稿' using errcode='42501'; end if;
 if (j.result->>'plan_id') is not null then return (j.result->>'plan_id')::uuid; end if;
 if p_draft is null or jsonb_typeof(p_draft) <> 'object' or jsonb_typeof(p_draft->'shots') <> 'array'
    or jsonb_array_length(p_draft->'shots') not between 1 and 60 or pg_column_size(p_draft) > 262144 then
  raise exception '分镜草稿格式无效（需要 1–60 个镜头）' using errcode='check_violation';
 end if;
 if j.created_by is null or not exists (
  select 1 from public.organization_members m
  join public.organization_roles r on r.organization_id = m.organization_id and r.role_key = m.role
  where m.organization_id = j.organization_id and m.user_id = j.created_by and 'content.manage' = any(r.permissions)
 ) then
  raise exception '任务发起人已无视频创作权限，拒绝写入' using errcode='42501';
 end if;
 insert into public.video_plans(organization_id, work_item_id, title, aspect_ratio, target_seconds, style, default_voice, created_by)
 values (j.organization_id, j.work_item_id,
  left(coalesce(nullif(btrim(p_draft->>'title'), ''), '未命名分镜'), 160),
  coalesce(nullif(p_draft->>'aspect_ratio', ''), j.payload->>'aspect_ratio', '9:16'),
  coalesce((p_draft->>'target_seconds')::integer, (j.payload->>'target_seconds')::integer, 30),
  left(coalesce(p_draft->>'style', j.payload->>'style', ''), 1000),
  coalesce(nullif(p_draft->>'default_voice', ''), j.payload->>'default_voice', 'zh-CN-XiaoxiaoNeural'), j.created_by)
 returning id into v_plan;
 for v_shot in select * from jsonb_array_elements(p_draft->'shots') loop
  v_pos := v_pos + 1;
  insert into public.video_shots(organization_id, plan_id, position, shot_size, camera_motion, motion_mode, visual_prompt, narration, voice,
   sfx_description, target_duration_ms, created_by)
  values (j.organization_id, v_plan, v_pos, coalesce(v_shot->>'shot_size', 'medium'), coalesce(v_shot->>'camera_motion', 'zoom_in'),
   coalesce(v_shot->>'motion_mode', 'local_ken_burns'), left(coalesce(v_shot->>'visual_prompt', ''), 2000), left(coalesce(v_shot->>'narration', ''), 1000),
   nullif(v_shot->>'voice', ''), left(coalesce(v_shot->>'sfx_description', ''), 500), coalesce((v_shot->>'target_duration_ms')::integer, 4000), j.created_by);
 end loop;
 update public.agent_jobs set result = coalesce(result, '{}'::jsonb) || jsonb_build_object('plan_id', v_plan, 'shots', v_pos) where id = j.id;
 insert into public.audit_events(organization_id, actor_user_id, action, target_type, target_id, metadata)
 values (j.organization_id, null, 'video_storyboard.drafted', 'video_plan', v_plan::text,
  jsonb_build_object('agent_job_id', j.id, 'shots', v_pos, 'model', p_draft->>'model'));
 return v_plan;
end; $$;
revoke all on function public.write_video_draft(uuid, bigint, jsonb) from public, anon, authenticated;
grant execute on function public.write_video_draft(uuid, bigint, jsonb) to service_role;

create function public.node_write_video_draft(p_token text, p_job_id uuid, p_lease_epoch bigint, p_draft jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
begin
 perform private.node_job(p_token, p_job_id);
 return public.write_video_draft(p_job_id, p_lease_epoch, p_draft);
end; $$;
revoke all on function public.node_write_video_draft(text, uuid, bigint, jsonb) from public;
grant execute on function public.node_write_video_draft(text, uuid, bigint, jsonb) to anon, authenticated, service_role;
-- <<< 20261126100100_video_mvp.sql

-- >>> 20261126100200_chat.sql
-- DB3 (0.5): Chat storage (docs/database.md §4.5, invariant 8). The loop and the HTTP/SSE entry come with R3.
--   * chat_sessions: one conversation, owned by one member, optionally on a work item card.
--   * chat_messages: append-only. A human writes only `user` messages via send_chat_message; `assistant`
--     messages come only from a runner node holding a running chat_turn job for that session
--     (node_append_chat_message). seq and created_at are assigned by the server under the session row lock.

create table public.chat_sessions (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete cascade,
 owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
 work_item_id uuid,
 title text not null default '' check (char_length(title) <= 200),
 exec_session jsonb not null default '{}'::jsonb check (jsonb_typeof(exec_session) = 'object' and pg_column_size(exec_session) <= 16384),
 last_seq integer not null default 0 check (last_seq >= 0),
 archived_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 unique (organization_id, id),
 foreign key (organization_id, work_item_id) references public.work_items(organization_id, id) on delete set null (work_item_id)
);
comment on table public.chat_sessions is 'Chat 会话。可挂在某张事项卡上；exec_session 存 CLI / 模型会话信息（由节点写）。';
create index chat_sessions_owner_idx on public.chat_sessions (organization_id, owner_id, updated_at desc);
create index chat_sessions_work_item_idx on public.chat_sessions (organization_id, work_item_id) where work_item_id is not null;

create table public.chat_messages (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null,
 session_id uuid not null,
 seq integer not null check (seq >= 1),
 role text not null check (role in ('user','assistant','system','tool')),
 content text not null check (char_length(content) <= 200000),
 agent_job_id uuid,
 created_at timestamptz not null default now(),
 unique (organization_id, id),
 unique (session_id, seq),
 foreign key (organization_id, session_id) references public.chat_sessions(organization_id, id) on delete cascade,
 foreign key (organization_id, agent_job_id) references public.agent_jobs(organization_id, id) on delete set null (agent_job_id)
);
comment on table public.chat_messages is 'Chat 消息，只追加。user 消息只能经 send_chat_message 写入；assistant 消息只能由执行节点写入。';
create index chat_messages_job_idx on public.chat_messages (organization_id, agent_job_id) where agent_job_id is not null;

-- Session guard: owner and organization are fixed; only title / work item / archive state change from the browser.
create function private.guard_chat_session() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op = 'INSERT' then
  if auth.uid() is not null then new.owner_id := auth.uid(); end if;
  new.last_seq := 0; new.created_at := now(); new.updated_at := now();
  if new.work_item_id is not null and not exists (select 1 from public.work_items w where w.id = new.work_item_id and w.organization_id = new.organization_id) then
   raise exception '事项不存在或不属于该组织' using errcode='check_violation';
  end if;
  return new;
 end if;
 if new.organization_id is distinct from old.organization_id or new.owner_id is distinct from old.owner_id
  or new.created_at is distinct from old.created_at then
  raise exception '会话归属不可修改' using errcode='check_violation';
 end if;
 if coalesce(current_setting('app.chat_write', true), '') <> 'on'
  and (new.last_seq is distinct from old.last_seq or new.exec_session is distinct from old.exec_session) then
  raise exception '会话序号与执行信息只能由服务端写入' using errcode='42501';
 end if;
 new.updated_at := now();
 return new;
end; $$;
revoke all on function private.guard_chat_session() from public, anon, authenticated;
create trigger chat_session_guard before insert or update on public.chat_sessions
 for each row execute function private.guard_chat_session();

alter table public.chat_sessions enable row level security;
alter table public.chat_messages enable row level security;
revoke all on public.chat_sessions, public.chat_messages from anon, authenticated, service_role;
grant select, delete on public.chat_sessions to authenticated;
grant insert (organization_id, work_item_id, title) on public.chat_sessions to authenticated;
grant update (work_item_id, title, archived_at) on public.chat_sessions to authenticated;
grant select on public.chat_messages to authenticated;
grant select on public.chat_sessions, public.chat_messages to service_role;

create policy chat_sessions_read on public.chat_sessions for select to authenticated
 using (owner_id = (select auth.uid()) and (select private.has_organization_permission(organization_id, 'content.view')));
create policy chat_sessions_insert on public.chat_sessions for insert to authenticated
 with check ((select private.has_organization_permission(organization_id, 'content.view')));
create policy chat_sessions_update on public.chat_sessions for update to authenticated
 using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy chat_sessions_delete on public.chat_sessions for delete to authenticated
 using (owner_id = (select auth.uid()));
create policy chat_messages_read on public.chat_messages for select to authenticated
 using (exists (select 1 from public.chat_sessions s where s.id = session_id and s.owner_id = (select auth.uid())));

create function private.append_chat_message(p_session public.chat_sessions, p_role text, p_content text, p_job uuid)
returns public.chat_messages language plpgsql security definer set search_path='' as $$
declare m public.chat_messages; v_seq integer := p_session.last_seq + 1;
begin
 if char_length(coalesce(p_content, '')) not between 1 and 200000 then
  raise exception '消息内容需为 1–200000 字' using errcode='check_violation';
 end if;
 perform set_config('app.chat_write', 'on', true);
 update public.chat_sessions set last_seq = v_seq where id = p_session.id;
 perform set_config('app.chat_write', 'off', true);
 insert into public.chat_messages(organization_id, session_id, seq, role, content, agent_job_id)
 values (p_session.organization_id, p_session.id, v_seq, p_role, p_content, p_job)
 returning * into m;
 return m;
end; $$;
revoke all on function private.append_chat_message(public.chat_sessions, text, text, uuid) from public, anon, authenticated;

-- A human sends a message; with p_run_agent the matching chat_turn job is queued in the same transaction.
create function public.send_chat_message(p_session_id uuid, p_content text, p_run_agent boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.chat_sessions; m public.chat_messages; j public.agent_jobs;
begin
 if auth.uid() is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
  raise exception '需要登录' using errcode='42501';
 end if;
 select * into s from public.chat_sessions where id = p_session_id for update;
 if not found or s.owner_id <> auth.uid() or not private.has_organization_permission(s.organization_id, 'content.view') then
  raise exception '会话不存在或没有权限' using errcode='42501';
 end if;
 if s.archived_at is not null then raise exception '会话已归档' using errcode='check_violation'; end if;
 m := private.append_chat_message(s, 'user', p_content, null);
 if p_run_agent then
  j := public.enqueue_agent_job(s.organization_id, 'chat_turn', 'chat_turn:' || m.id::text,
   jsonb_build_object('schema_version', 1, 'session_id', s.id, 'message_id', m.id, 'seq', m.seq),
   'chat_session', s.id::text, null, null, 1, null, s.work_item_id);
  update public.chat_messages set agent_job_id = j.id where id = m.id;
  m.agent_job_id := j.id;
 end if;
 return jsonb_build_object('message_id', m.id, 'seq', m.seq, 'agent_job_id', m.agent_job_id);
end; $$;
revoke all on function public.send_chat_message(uuid, text, boolean) from public, anon, service_role;
grant execute on function public.send_chat_message(uuid, text, boolean) to authenticated;

-- The node answers: only for a running chat_turn job it holds, bound to this session.
create function public.node_append_chat_message(p_token text, p_job_id uuid, p_lease_epoch bigint, p_content text, p_exec_session jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.agent_jobs := private.node_job(p_token, p_job_id); s public.chat_sessions; m public.chat_messages;
begin
 if j.lease_epoch is distinct from p_lease_epoch then raise exception '任务租约已失效（lease_epoch 不匹配），拒绝写入' using errcode='P0002'; end if;
 if j.kind <> 'chat_turn' then raise exception '只有 Chat 回合任务可以写入回复' using errcode='42501'; end if;
 select * into s from public.chat_sessions
 where id::text = j.payload->>'session_id' and organization_id = j.organization_id for update;
 if not found then raise exception '会话不存在' using errcode='P0002'; end if;
 m := private.append_chat_message(s, 'assistant', p_content, j.id);
 if p_exec_session is not null then
  if jsonb_typeof(p_exec_session) <> 'object' or pg_column_size(p_exec_session) > 16384 then
   raise exception '会话执行信息格式无效' using errcode='check_violation';
  end if;
  perform set_config('app.chat_write', 'on', true);
  update public.chat_sessions set exec_session = p_exec_session where id = s.id;
  perform set_config('app.chat_write', 'off', true);
 end if;
 return jsonb_build_object('message_id', m.id, 'seq', m.seq);
end; $$;
revoke all on function public.node_append_chat_message(text, uuid, bigint, text, jsonb) from public;
grant execute on function public.node_append_chat_message(text, uuid, bigint, text, jsonb) to anon, authenticated, service_role;
-- <<< 20261126100200_chat.sql

-- >>> 20261126100300_retire_v1.sql
-- Retire release (0.5, docs/database.md §3, §7, DB-D3 / DB-D6): the V1 tables go after one last backfill
-- and a reconciliation that refuses to drop anything that is not accounted for in the 0.5 tables.
--   V1 capture: signals, selections, intake_receipts, intake_oauth_{requests,grants,tokens} (+ intake_oauth RPC)
--   V1 content: content_projects, content_project_assets, content_revisions, content_review_events
--   Knowledge (not in the MVP): knowledge_entries, decision_memories — the worker reads knowledge-base/ files.
-- content_documents: work_item_id becomes NOT NULL, project_id is dropped. Review history keeps flowing into
-- audit_events (content.<status>); revisions keep counting but no snapshot table exists any more.

-- ── 1. Last backfill + reconciliation (aborts the whole release on any gap) ──
do $reconcile$
declare r jsonb; n bigint;
begin
 r := private.backfill_v1();
 raise notice 'backfill_v1 (final): %', r;

 select count(*) into n from public.intake_receipts x
 where not exists (select 1 from public.intake_events e where e.payload -> 'legacy' ->> 'receipt_id' = x.id::text);
 if n > 0 then raise exception 'reconcile: % intake_receipts have no intake_events row', n; end if;

 select count(*) into n from public.signals s
 where not exists (select 1 from public.intake_events e where e.payload -> 'legacy' ->> 'signal_id' = s.id::text);
 if n > 0 then raise exception 'reconcile: % signals have no intake_events row', n; end if;

 select count(*) into n from public.selections x
 where not exists (select 1 from public.work_items w where w.brief -> 'legacy' ->> 'selection_id' = x.id::text);
 if n > 0 then raise exception 'reconcile: % selections have no work_items row', n; end if;

 select count(*) into n from public.content_projects p
 where not exists (select 1 from public.work_items w where w.brief -> 'legacy' ->> 'content_project_id' = p.id::text);
 if n > 0 then raise exception 'reconcile: % content_projects have no work_items row', n; end if;

 select count(*) into n from public.content_review_events v
 where not exists (select 1 from public.audit_events a where a.metadata -> 'legacy' ->> 'review_event_id' = v.id::text);
 if n > 0 then raise exception 'reconcile: % content_review_events have no audit_events row', n; end if;

 select count(*) into n from public.content_documents where work_item_id is null;
 if n > 0 then raise exception 'reconcile: % content_documents are not on a work item', n; end if;

 select count(*) into n from public.content_project_assets;
 if n > 0 then raise exception 'reconcile: content_project_assets has % rows; linked assets are not carried over', n; end if;
end $reconcile$;

-- ── 2. content_documents: card only, no snapshot table ──
create or replace function private.guard_cloud_content() returns trigger language plpgsql set search_path='' as $$
begin
 if auth.uid() is null then raise exception '需要登录' using errcode='42501'; end if;
 if tg_op='INSERT' then
  new.created_by:=auth.uid(); new.created_at:=now(); new.updated_at:=now();
  if new.status<>'draft' then raise exception '新稿件必须为草稿'; end if;
  new.revision:=1;
  return new;
 end if;
 if new.organization_id is distinct from old.organization_id or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
  raise exception '不能修改所属组织或创建记录';
 end if;
 new.updated_at:=now();
 if new.work_item_id is distinct from old.work_item_id or new.platform<>old.platform or new.revision<>old.revision then
  raise exception '不能修改稿件归属或版本号';
 end if;
 if new.title is distinct from old.title or new.body is distinct from old.body then
  if not private.has_organization_permission(new.organization_id,'content.manage') then raise exception '没有编辑权限' using errcode='42501'; end if;
  new.revision:=old.revision+1; new.status:='draft'; new.review_note:='';
 elsif new.status<>old.status then
  if new.status='in_review' then
   if old.status not in ('draft','changes_requested') or btrim(new.body)='' or not private.has_organization_permission(new.organization_id,'content.manage') then raise exception '稿件不能提交审核'; end if;
  elsif new.status in ('approved','changes_requested') then
   if old.status<>'in_review' or not private.has_organization_permission(new.organization_id,'content.review') then raise exception '需要审核权限及待审核稿件' using errcode='42501'; end if;
   if new.status='changes_requested' and btrim(new.review_note)='' then raise exception '请填写退回原因'; end if;
  else raise exception '无效的审核状态变化'; end if;
 elsif new.review_note is distinct from old.review_note then raise exception '审核意见必须随审核决定提交';
 end if;
 return new;
end; $$;

-- Review history → audit_events (same shape the backfill produced: action content.<status>, metadata.revision/note).
create or replace function private.snapshot_cloud_document() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception '需要登录'; end if;
 if tg_op='INSERT' or new.status<>old.status then
  insert into public.audit_events(organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (new.organization_id, auth.uid(), 'content.' || new.status, 'content_document', new.id::text,
   jsonb_build_object('revision', new.revision, 'note', new.review_note));
 end if;
 return new;
end; $$;

alter table public.content_documents drop constraint if exists content_documents_owner_present;
alter table public.content_documents drop constraint if exists content_documents_organization_id_project_id_fkey;
alter table public.content_documents drop constraint if exists content_documents_project_id_platform_key;
drop index if exists public.content_documents_organization_id_project_id_idx;
alter table public.content_documents drop column project_id;
alter table public.content_documents alter column work_item_id set not null;

-- ── 3. Knowledge comes from repo files; node_draft_context returns only the document, card and source ──
create or replace function public.node_draft_context(p_token text, p_job_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.agent_jobs := private.node_job(p_token, p_job_id); d public.content_documents; w jsonb; src jsonb;
begin
 select * into d from public.content_documents
 where id::text = j.payload->'target'->>'id' and organization_id = j.organization_id and j.payload->'target'->>'type' = 'content_document';
 if not found then raise exception '任务目标稿件不存在' using errcode='P0002'; end if;
 select jsonb_build_object('id', x.id, 'kind', x.kind, 'title', x.title, 'brief', x.brief) into w
 from public.work_items x where x.id = d.work_item_id and x.organization_id = j.organization_id;
 if w is not null then
  select jsonb_build_object('id', e.id, 'text', e.text, 'url', e.url, 'created_at', e.created_at) into src
  from public.intake_events e where e.work_item_id = d.work_item_id and e.organization_id = j.organization_id
  order by e.created_at, e.id limit 1;
 end if;
 return jsonb_build_object(
  'document', jsonb_build_object('id', d.id, 'organization_id', d.organization_id, 'work_item_id', d.work_item_id,
    'platform', d.platform, 'title', d.title, 'body', d.body, 'revision', d.revision),
  'workItem', w,
  'source', src);
end; $$;

-- ── 4. Drop the retired objects (no CASCADE: an unexpected dependency must fail the release) ──
drop function if exists public.intake_oauth(text, jsonb);
drop function if exists private.backfill_v1();
drop table public.intake_oauth_tokens;
drop table public.intake_oauth_grants;
drop table public.intake_oauth_requests;
drop table public.intake_receipts;
drop table public.content_project_assets;
drop table public.content_projects;
drop table public.selections;
drop table public.signals;
drop table public.content_review_events;
drop table public.content_revisions;
drop table public.decision_memories;
drop table public.knowledge_entries;
drop function if exists private.guard_knowledge_memory();
